// --- 효과음 ---

// Base64로 인코딩된 오디오 데이터입니다.
// 이 방식은 외부 파일 종속성을 제거하여 로딩 오류를 근본적으로 방지합니다.
const BASE64_SOUNDS = {
  // 공격 성공 (explosion.mp3)
  hit: 'data:audio/mpeg;base64,',
  
  // 공격 실패 (select.mp3)
  miss: 'data:audio/mpeg;base64,',
  
  // 함선 침몰 (water_bubble.mp3)
  sunk: 'data:audio/mpeg;base64,'
};

export type SoundType = keyof typeof BASE64_SOUNDS;

/**
 * 지정된 유형의 효과음을 재생합니다.
 * 이 함수는 호출될 때마다 새로운 Audio 객체를 생성하여 재생합니다.
 * 내장된 Base64 데이터를 사용하므로 파일 경로 관련 오류가 발생하지 않습니다.
 * @param type 재생할 사운드의 유형 ('hit', 'sunk', 'miss')
 */
export const playEffectSound = (type: SoundType) => {
  try {
    const audioSrc = BASE64_SOUNDS[type];
    
    // 데이터가 유효한 데이터 URI 형식인지 간단히 확인합니다.
    if (!audioSrc || !audioSrc.startsWith('data:audio')) {
      // 플레이스홀더 텍스트가 남아있는 경우, 오류를 출력하지 않고 조용히 넘어갑니다.
      if (!audioSrc.includes('여기에')) {
         console.error(`'${type}'에 대한 오디오 데이터가 유효하지 않습니다. 'data:audio/mpeg;base64,...' 형식인지 확인해주세요.`);
      }
      return;
    }

    const audio = new Audio(audioSrc);
    audio.play().catch(e => {
      // 사용자가 페이지와 상호작용하기 전에 오디오를 재생하려고 할 때 발생하는 일반적인 오류입니다.
      // 콘솔에 오류를 남기되, 사용자 경험을 해치지 않도록 조용히 처리합니다.
      if (e.name !== 'NotAllowedError') {
        console.error(`'${type}' 사운드 재생 중 오류 발생:`, e);
      }
    });
  } catch (error) {
    console.error(`'${type}' 사운드 데이터를 로드하는 중 오류 발생:`, error);
  }
};
